package com.trademesh.strategy;

import com.trademesh.strategy.enums.Confidence;
import com.trademesh.strategy.enums.SignalType;
import lombok.AllArgsConstructor;
import lombok.Builder;
import lombok.Data;
import lombok.NoArgsConstructor;

import java.time.LocalDateTime;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.UUID;

/**
 * Represents a trading signal generated by a strategy.
 *
 * <p>A trade signal encapsulates a complete trading opportunity including:
 * <ul>
 *   <li>Signal metadata (ID, symbol, strategy name)</li>
 *   <li>Signal type (ENTER, EXIT, ADJUST)</li>
 *   <li>Multi-leg structure (list of TradeLeg objects)</li>
 *   <li>Risk/reward metrics (expected credit, max loss)</li>
 *   <li>Confidence level and reasoning</li>
 *   <li>Timestamp of generation</li>
 * </ul>
 *
 * <p>This is the core output of any trading strategy and serves as input
 * to the execution pipeline.
 */
@Data
@Builder
@NoArgsConstructor
@AllArgsConstructor
public class TradeSignal {

    /**
     * Unique identifier for this signal (UUID).
     * Used for tracking and audit purposes.
     */
    private UUID signalId;

    /**
     * Trading symbol (e.g., "NIFTY50", "BANKNIFTY").
     */
    private String symbol;

    /**
     * Name of the strategy that generated this signal.
     * Examples: "IronCondor", "CallSpread", "CashSecuredPut"
     */
    private String strategyName;

    /**
     * Type of signal (ENTER, EXIT, or ADJUST).
     * Determines the action to be taken.
     */
    private SignalType signalType;

    /**
     * List of trade legs that make up this signal.
     * A signal can have multiple legs (e.g., 4 legs for an iron condor).
     */
    private List<TradeLeg> legs;

    /**
     * Expected credit/debit for the entire strategy.
     * Positive value = credit received (income strategy).
     * Negative value = debit paid (debit strategy).
     */
    private Double expectedCredit;

    /**
     * Maximum loss if the strategy goes against us.
     * Used for risk management and position sizing.
     */
    private Double maxLoss;

    /**
     * Confidence level of this signal (LOW, MEDIUM, HIGH).
     * Based on strategy's internal scoring and market conditions.
     */
    private Confidence confidence;

    /**
     * Plain English explanation of why this signal was generated.
     * Examples:
     * - "VIX at 15, NIFTY at support, IV rank 60% - good risk/reward for iron condor"
     * - "Breakout above resistance with volume confirmation"
     * - "Profit target hit, exiting position"
     */
    private String reason;

    /**
     * Timestamp when this signal was generated.
     */
    @Builder.Default
    private LocalDateTime generatedAt = LocalDateTime.now();

    /**
     * Strategy-specific metadata for signal enrichment.
     * Used by strategies to pass additional context to execution layer.
     * For Iron Condor: stores P&L matrix, confidence score, market metrics.
     * Key examples: "maxProfit", "maxLoss", "upperBreakeven", "confidenceScore", etc.
     */
    @Builder.Default
    private Map<String, String> metadata = new HashMap<>();
}
